 void refresh(const ParameterSnapshot& p){const double rate=owner.getSampleRate()>0?owner.getSampleRate():48000;if(rate!=displayedRate){displayedRate=rate;if(sa)slider.updateText();}bool enabled=ui::controlEnabled(parameter,p);slider.setEnabled(enabled);choice.setEnabled(enabled);toggle.setEnabled(enabled);juce::String why;if(!enabled)why=p[Param::RoutingMode]>.5f&&(parameter==Param::MixAmount||parameter==Param::DirectLevel)?"Send mode: effective Mix 100%, Direct muted; stored Insert value preserved":"Clean mode ignores Drive";slider.setTooltip(why.isEmpty()?juce::String(parameterDefinition(parameter).name)+" - drag; Shift for fine adjustment; type value; double-click default":why);label.setTooltip(why);}
