AdlibEditor::~AdlibEditor(){stopTimer();releaseThrow();detailViewport.setViewedComponent(nullptr,false);setLookAndFeel(nullptr);}
void AdlibEditor::releaseThrow(){auto s=processor.snapshot();processor.setPerformance(Param::ThrowActive,throwGesture.lostFocus(s[Param::ThrowLatch]>.5f,s[Param::ThrowActive]>.5f));}
void AdlibEditor::focusLost(FocusChangeType){releaseThrow();}
