void AdlibEditor::selectPage(int index){page=index;details.clear();auto add=[this](Param p){auto c=std::make_unique<ParameterControl>(processor,p);detailBody.addAndMakeVisible(*c);details.push_back(std::move(c));};auto range=[&](Param first,Param last){for(auto i=std::size_t(first);i<=std::size_t(last);++i)add(Param(i));};switch(page){case 0:range(Param::GateEnabled,Param::DeessListen);break;case 1:range(Param::CharacterEnabled,Param::CharacterTrim);break;case 2:range(Param::DoubleEnabled,Param::StereoWidth);break;case 3:range(Param::DelayEnabled,Param::DelayThrowMode);break;case 4:range(Param::ReverbEnabled,Param::DuckRelease);break;default:add(Param::DirectLevel);add(Param::LimiterEnabled);add(Param::LimiterCeiling);add(Param::LimiterRelease);break;}for(int i=0;i<6;++i)tabs[std::size_t(i)].setToggleState(i==page,juce::dontSendNotification);auto state=processor.uiState();state.page=page;processor.setUiState(state);resized();}
void AdlibEditor::timerCallback(){auto p=processor.snapshot();for(auto&c:mainControls)c->refresh(p);for(auto&c:details)c->refresh(p);auto m=processor.readMeters();heldInput=juce::jmax(heldInput,m.inputPeakDb);heldOutput=juce::jmax(heldOutput,m.outputPeakDb);auto db=[](float v){return v<=-100?juce::String("-inf"):juce::String(v,1);};meterLabel.setText("IN "+db(m.inputPeakDb)+" / HOLD "+db(heldInput)+"  OUT "+db(m.outputPeakDb)+" / HOLD "+db(heldOutput)+" dBFS     GATE "+juce::String(m.gateReductionDb,1)+"   DEESS "+juce::String(m.deessReductionDb,1)+"   LIMIT "+juce::String(m.limiterReductionDb,1)+" dB     CORR "+(std::isfinite(m.correlation)?juce::String(m.correlation,2):juce::String("N/A")),juce::dontSendNotification);auto state=processor.uiState();presetLabel.setText(juce::String(state.preset)+(state.modified?" *":""),juce::dontSendNotification);a.setToggleState(processor.activeAB()==0,juce::dontSendNotification);b.setToggleState(processor.activeAB()==1,juce::dontSendNotification);throwButton.setToggleState(p[Param::ThrowActive]>.5f,juce::dontSendNotification);juce::StringArray status;if(m.listen)status.add("LISTEN: HIGH BAND");if(m.clearing)status.add("CLEARING TAILS");if(m.frozen)status.add("FREEZE HELD");if(status.isEmpty())status.add(juce::String(m.tempo,1)+(m.manualTempo?" MANUAL":" HOST")+(m.delayClamped?" CLAMP":""));statusLabel.setText(status.joinIntoString("\n"),juce::dontSendNotification);juce::String overrides=p[Param::RoutingMode]>.5f?"SEND: effective Mix 100% / Direct muted. Stored Insert values retained.":"";const auto error=processor.lastError();if(error.isNotEmpty())overrides+=(overrides.isEmpty()?"":" / ")+error;overrideLabel.setText(overrides,juce::dontSendNotification);overrideLabel.setTooltip(overrides);clearing=m.clearing;for(auto* button:{&freeze,&clear,&a,&b,&copy,&reset,&fullReset,&browse,&previous,&next,&browserLoad,&save})button->setEnabled(!clearing);throwButton.setEnabled(!clearing);latch.setEnabled(!clearing);routing.setEnabled(!clearing);list.setEnabled(!clearing);search.setEnabled(!clearing);for(auto& c:mainControls)c->setEnabled(!clearing);for(auto& c:details)c->setEnabled(!clearing);for(auto& c:topControls)c->setEnabled(!clearing);diagnosticLabel.setText("DIAG "+juce::String(static_cast<juce::uint64>(m.diagnostics)),juce::dontSendNotification);}
void AdlibEditor::showBrowser(bool show){if(show&&(clearing||processor.readMeters().clearing))return;browserVisible=show;browserBody.setVisible(show);for(auto& c:mainControls)c->setVisible(!show);detailViewport.setVisible(!show);for(auto&tab:tabs)tab.setVisible(!show);if(show){refreshBrowser();browserBody.toFront(false);search.grabKeyboardFocus();}repaint();}
void AdlibEditor::refreshBrowser(){
 filteredFactories.clear();filteredUsers.clear();filteredUserNames.clear();const auto query=search.getText().trim();const auto& bank=factoryPresets();
 for(int i=0;i<24;++i)if(query.isEmpty()||juce::String(bank[std::size_t(i)].name).containsIgnoreCase(query)||juce::String(bank[std::size_t(i)].family).containsIgnoreCase(query))filteredFactories.push_back(i);
 // Message-thread-only bounded preset metadata reads; never load source audio.
 const auto directory=processor.userPresetDirectory();PresetStore store(std::filesystem::path(directory.getFullPathName().toWideCharPointer()));juce::Array<juce::File> files;directory.findChildFiles(files,juce::File::findFiles,false,"*.json");int rejected=0;
 for(const auto& file:files){const auto result=store.load(std::filesystem::path(file.getFullPathName().toWideCharPointer()));if(!result){++rejected;continue;}const auto name=juce::String::fromUTF8(result.preset.name.c_str());if(query.isEmpty()||name.containsIgnoreCase(query)){filteredUsers.add(file);filteredUserNames.add(name);}}
 browserNotice.setText(juce::String(getNumRows())+" matching presets"+(rejected?" / "+juce::String(rejected)+" invalid user files ignored":"")+". Arrow navigation does not load.",juce::dontSendNotification);list.updateContent();list.deselectAllRows();
}
int AdlibEditor::getNumRows(){return int(filteredFactories.size())+filteredUsers.size();}
void AdlibEditor::paintListBoxItem(int row,juce::Graphics&g,int w,int h,bool selected){if(selected)g.fillAll(juce::Colour(0xff285654));g.setColour(juce::Colour(0xffeee9d9));g.setFont(14.f);juce::String text;if(row>=0&&row<int(filteredFactories.size())){const auto& f=factoryPresets()[std::size_t(filteredFactories[std::size_t(row)])];text=juce::String(f.id)+"  "+f.name+"    / "+f.family;}else {int i=row-int(filteredFactories.size());if(juce::isPositiveAndBelow(i,filteredUsers.size()))text="USER  "+filteredUserNames[i];}g.drawText(text,8,0,w-16,h,juce::Justification::left);}
void AdlibEditor::loadSelected(){if(clearing||processor.readMeters().clearing)return;int row=list.getSelectedRow();if(row<0)return;if(row<int(filteredFactories.size())){factoryIndex=filteredFactories[std::size_t(row)];processor.loadFactory(factoryIndex);}else{int i=row-int(filteredFactories.size());if(juce::isPositiveAndBelow(i,filteredUsers.size()))processor.loadUserPreset(filteredUsers[i]);}showBrowser(false);}
void AdlibEditor::returnKeyPressed(int){if(ui::shouldLoadPreset(ui::BrowserAction::confirm,clearing))loadSelected();}void AdlibEditor::listBoxItemClicked(int row,const juce::MouseEvent&){if(row>=0&&ui::shouldLoadPreset(ui::BrowserAction::pointerActivation,clearing)){list.selectRow(row);loadSelected();}}
void AdlibEditor::saveAs(){auto* window=new juce::AlertWindow("Save ADLIB-93 preset","Save a complete parameter preset. No captured vocal audio is stored.",juce::MessageBoxIconType::NoIcon);window->addTextEditor("name",juce::String(processor.uiState().preset),"Name");window->addButton("Save",1,juce::KeyPress(juce::KeyPress::returnKey));window->addButton("Cancel",0,juce::KeyPress(juce::KeyPress::escapeKey));juce::Component::SafePointer<AdlibEditor> self(this);window->enterModalState(true,juce::ModalCallbackFunction::create([self,window](int result){if(result==1&&self!=nullptr)self->processor.saveUserPreset(window->getTextEditorContents("name"));}),true);}
